const keyMap={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'};addEventListener('keydown',e=>{if(chapter!==2||document.querySelector('dialog[open]')||e.target.matches('input,select,textarea'))return;if(keyMap[e.key]){e.preventDefault();steer[keyMap[e.key]]=true;target=null;autoMow=false;}});addEventListener('keyup',e=>{if(keyMap[e.key])steer[keyMap[e.key]]=false;});addEventListener('blur',()=>Object.keys(steer).forEach(k=>steer[k]=false));
const pointer=new THREE.Vector2(),raycaster=new THREE.Raycaster(),plane=new THREE.Plane(new THREE.Vector3(0,1,0),-.15),hit=new THREE.Vector3();
function lawnPoint(e){pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);if(raycaster.ray.intersectPlane(plane,hit))return new THREE.Vector3(THREE.MathUtils.clamp(hit.x,-2.4,1.8),.15,THREE.MathUtils.clamp(hit.z,-1.35,2));return null;}
canvas.addEventListener('pointerdown',e=>{if(chapter===2&&mode==='mow'){target=lawnPoint(e);autoMow=false;document.querySelector('#tour-toggle').textContent='▶ Auto mow';document.querySelector('#tour-toggle').setAttribute('aria-pressed','false');document.querySelector('#play-status').textContent='Nice. Follow your own line.';}else{dragging=true;dragX=e.clientX;dragY=e.clientY;canvas.setPointerCapture(e.pointerId);}});
canvas.addEventListener('pointermove',e=>{mouseX=(e.clientX/innerWidth-.5)*2;mouseY=(e.clientY/innerHeight-.5)*2;if(dragging){userOrbit+=(e.clientX-dragX)*.004;userTilt=THREE.MathUtils.clamp(userTilt+(e.clientY-dragY)*.002,-.25,.25);dragX=e.clientX;dragY=e.clientY;}if(chapter===2&&mode==='mow'){const point=lawnPoint(e);if(point){cursorRing.position.copy(point);cursorRing.visible=true;}}});['pointerup','pointercancel','lostpointercapture'].forEach(t=>canvas.addEventListener(t,()=>dragging=false));canvas.addEventListener('pointerleave',()=>cursorRing.visible=false);
document.querySelector('#reset-camera').addEventListener('click',()=>{userTilt=0;if(window.gsap&&!reduced){const p={value:userOrbit};gsap.to(p,{value:0,duration:1.1,onUpdate:()=>userOrbit=p.value});}else userOrbit=0;});
document.querySelector('#light-toggle').addEventListener('click',()=>{isDusk=!isDusk;document.querySelector('#light-toggle').setAttribute('aria-pressed',String(isDusk));document.querySelector('#light-label').textContent=isDusk?'Golden dusk':'Daylight';document.querySelector('.sun-icon').textContent=isDusk?'☾':'☀';host.style.background=isDusk?'radial-gradient(ellipse at 65% 20%,#716954 0%,#30493b 38%,#102c29 80%)':'';});
document.querySelector('#breeze-toggle').addEventListener('click',()=>{const strong=breezeTarget<1;breezeTarget=strong?1.75:.65;document.querySelector('#breeze-toggle').setAttribute('aria-pressed',String(strong));document.querySelector('#breeze-toggle').textContent=strong?'Windy':'Breeze';});
const pauseButton=document.querySelector('#motion-toggle');function syncPause(){pauseButton.textContent=paused?'▶':'Ⅱ';pauseButton.setAttribute('aria-pressed',String(paused));pauseButton.setAttribute('aria-label',paused?'Resume ambient animation':'Pause ambient animation');}syncPause();pauseButton.addEventListener('click',()=>{paused=!paused;syncPause();});
window.addEventListener('jcp-chapter',e=>{chapter=e.detail;if(chapter!==2){target=null;autoMow=false;cursorRing.visible=false;Object.keys(steer).forEach(k=>steer[k]=false);document.querySelector('#tour-toggle').textContent='▶ Auto mow';document.querySelector('#tour-toggle').setAttribute('aria-pressed','false');}});
const serviceMotion={value:0};window.addEventListener('jcp-service',e=>{const values={mow:0,edge:.85,clean:-.65,routine:1.55};if(window.gsap&&!reduced){gsap.to(serviceMotion,{value:values[e.detail],duration:1.6,overwrite:true,ease:'power3.inOut',onUpdate:()=>serviceBias=serviceMotion.value});}else serviceBias=values[e.detail];});
addEventListener('scroll',()=>scrollTarget=scrollY,{passive:true});
const desktopPoses=[{theta:.74,phi:.65,dist:17.1,x:-.24,y:-.045},{theta:-.64,phi:.76,dist:13.2,x:.26,y:0},{theta:.13,phi:1.04,dist:15.2,x:.025,y:-.035},{theta:2.95,phi:.68,dist:15,x:-.24,y:0}];
const mobilePoses=[{theta:.68,phi:.84,dist:27,x:0,y:-.23},{theta:-.6,phi:.97,dist:28,x:0,y:-.24},{theta:.12,phi:1.13,dist:30.6,x:0,y:.065},{theta:2.7,phi:.8,dist:27,x:0,y:-.22}];
let anchors=[];function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();anchors=[0,...['care','play','promise'].map(id=>document.getElementById(id).offsetTop)];}resize();addEventListener('resize',resize);new ResizeObserver(resize).observe(document.querySelector('main'));document.fonts?.ready.then(resize);
let last=0,time=0,duskMix=0,frame;
function tick(now){frame=requestAnimationFrame(tick);if(document.hidden||document.body.classList.contains("at-contact"))return;const dt=Math.min(.045,(now-last)/1000||.016);last=now;if(!paused)time+=dt;scrollCurrent+=(scrollTarget-scrollCurrent)*(reduced?1:1-Math.exp(-6*dt));const poses=innerWidth<760?mobilePoses:desktopPoses;let i=0;while(i<2&&scrollCurrent>anchors[i+1])i++;const next=Math.min(i+1,3),raw=THREE.MathUtils.clamp((scrollCurrent-(anchors[next]-innerHeight*.8))/(innerHeight*.8),0,1),t=raw*raw*(3-2*raw),pose={};for(const k of Object.keys(poses[0]))pose[k]=THREE.MathUtils.lerp(poses[i][k],poses[next][k],t);const careWeight=Math.max(0,1-Math.abs(scrollCurrent-anchors[1])/innerHeight);pose.phi=THREE.MathUtils.clamp(pose.phi+userTilt,.35,1.3);const theta=pose.theta+userOrbit+serviceBias*careWeight+(paused?0:mouseX*.035);camera.position.set(Math.sin(theta)*Math.cos(pose.phi)*pose.dist,Math.sin(pose.phi)*pose.dist,Math.cos(theta)*Math.cos(pose.phi)*pose.dist);camera.lookAt(0,.45,0);camera.setViewOffset(innerWidth,innerHeight,pose.x*innerWidth,pose.y*innerHeight,innerWidth,innerHeight);camera.updateProjectionMatrix();
  breeze.value+=(breezeTarget-breeze.value)*(1-Math.exp(-2*dt));if(!paused){wind.value=time;tree.rotation.z=Math.sin(time*.65)*.003*breeze.value;pollen.rotation.y=time*.025;pollen.position.y=Math.sin(time*.3)*.12;}
  duskMix+=(Number(isDusk)-duskMix)*(reduced?1:1-Math.exp(-3*dt));sun.intensity=2.5-duskMix*1.9;hemi.intensity=.9-duskMix*.55;rim.intensity=.6-duskMix*.3;scene.environmentIntensity=.45-duskMix*.25;sun.color.setRGB(1, .86-duskMix*.28,.61-duskMix*.33);ambientPoint.intensity=duskMix*5;lampMaterial.emissiveIntensity=.1+duskMix*3;lamps.forEach(l=>l.intensity=duskMix*2.8);
  let dx=0,dz=0,moving=false;if(chapter===2&&!document.querySelector('dialog[open]')){if(autoMow){target=route[autoIndex];if(mower.position.distanceTo(new THREE.Vector3(target.x,mower.position.y,target.z))<.1){autoIndex=(autoIndex+1)%route.length;target=route[autoIndex];}}dx=Number(steer.right)-Number(steer.left);dz=Number(steer.down)-Number(steer.up);if(target&&!dx&&!dz){dx=target.x-mower.position.x;dz=target.z-mower.position.z;if(Math.hypot(dx,dz)<.05){target=null;dx=0;dz=0;}}const length=Math.hypot(dx,dz);if(length>.01){dx/=length;dz/=length;const desired=Math.atan2(-dx,-dz);let difference=desired-mower.rotation.y;difference=Math.atan2(Math.sin(difference),Math.cos(difference));mower.rotation.y+=difference*(1-Math.exp(-7*dt));const turnFactor=Math.max(.12,Math.cos(difference));driveSpeed+=(.95*turnFactor-driveSpeed)*(1-Math.exp(-4*dt));const distance=dt*driveSpeed;mower.position.x=THREE.MathUtils.clamp(mower.position.x+dx*distance,-2.4,1.8);mower.position.z=THREE.MathUtils.clamp(mower.position.z+dz*distance,-1.35,2);wheels.forEach(w=>w.rotation.x-=distance/.185);mower.position.y=.11+Math.sin(now*.025)*.0015*driveSpeed;mower.rotation.z=Math.sin(difference)*driveSpeed*.012;moving=true;cutTime+=dt;if(cutTime>.065){cutGrass(mower.position.x,mower.position.z);cutTime=0;}}}
  if(!moving){driveSpeed=0;mower.rotation.z*=.85;}
  clippings.visible=moving||clipParticles.some(p=>p.life>0);clipParticles.forEach((p,i)=>{if(p.life>0){p.life-=dt*1.8;p.x+=p.vx*dt;p.z+=p.vz*dt;p.y+=dt*(p.life*2-.7);}dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(time*5+i,time*3,0);dummy.scale.setScalar(Math.max(0,p.life));dummy.updateMatrix();clippings.setMatrixAt(i,dummy.matrix);});if(clippings.visible)clippings.instanceMatrix.needsUpdate=true;
  renderer.render(scene,camera);
}
document.querySelectorAll('.chapter,#contact').forEach((section,index)=>{if(section.getBoundingClientRect().top<innerHeight*.45)chapter=index;});
frame=requestAnimationFrame(tick);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)last=performance.now();});
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(frame);host.classList.remove('webgl-ready');canvas.style.display='none';document.querySelector('#world-status').textContent='The 3D view paused. Refresh to reload, or continue to services and contact below.';});



